WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, SUM(CASE WHEN event_type = 'page_view' THEN is_new_burst ELSE 0 END) AS page_view_is_new_burst, MIN(event_time) AS started_at FROM sessionized GROUP BY CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END HAVING SUM(CASE WHEN event_type = 'page_view' THEN is_new_burst ELSE 0 END) > 0 ORDER BY page_view_is_new_burst DESC;
